window.VO = [{"id":"n01","text":"You've got one second.","at":0.24,"t0":0.12,"t1":1.39},{"id":"n02","text":"One man here killed someone.","at":2.94,"t0":1.47,"t1":3.105},{"id":"n03","text":"Pick him.","at":6.45,"t0":3.225,"t1":3.875},{"id":"n04","text":"Got a number? Now, which one do you trust with your house keys?","at":9.25,"t0":4.625,"t1":7.8},{"id":"n05","text":"Number one? He won't even look at you.","at":16.5,"t0":8.25,"t1":10.305},{"id":"n06","text":"Number two? He can't stop smiling.","at":21.11,"t0":10.555,"t1":12.72},{"id":"n07","text":"Number three hasn't blinked.","at":25.94,"t0":12.97,"t1":14.6},{"id":"n08","text":"And number four looks sorry. For what?","at":29.7,"t0":14.85,"t1":17.065},{"id":"n09","text":"You've got one second. Pick him.","at":35.03,"t0":17.515,"t1":19.26},{"id":"n10","text":"That's one killer, and one man you trust with your house.","at":40.22,"t0":20.11,"t1":23.055},{"id":"n11","text":"It's the same man.","at":47.55,"t0":23.775,"t1":24.89},{"id":"n12","text":"I did say one man.","at":52.88,"t0":26.44,"t1":27.76},{"id":"n13","text":"Look at the gap in his eyebrow. It's in all four photos.","at":56.32,"t0":28.16,"t1":31.265},{"id":"n14","text":"You stared at it for twenty-four seconds.","at":63.23,"t0":31.615,"t1":33.655},{"id":"n15","text":"Your brain decided in a tenth of a second, and then I handed you four reasons.","at":68.01,"t0":34.005,"t1":38.37},{"id":"n16","text":"You never judged him. You judged a photo.","at":77.54,"t0":38.77,"t1":41.04},{"id":"n17","text":"Everyone's got a villain photo.","at":82.88,"t0":41.44,"t1":43.105},{"id":"n18","text":"Yours is on your Aadhaar.","at":87.21,"t0":43.605,"t1":45.02},{"id":"n19","text":"And he's still got your keys.","at":91.24,"t0":45.62,"t1":47.14}];
